function readClinicianChats():ClinicianChat[]{try{const value=JSON.parse(localStorage.getItem(CLINICIAN_AI_KEY)||"[]");return Array.isArray(value)?value:[]}catch{return[]}}
const clinicianDefaultTitles=new Set(["New chat","New conversation","Nouvelle discussion","Nouvelle conversation","Nuevo chat","Nueva conversación","Neuer Chat","Neue Unterhaltung","محادثة جديدة"]);
const clinicianManageCopy:Record<Lang,Record<string,string>>={
 en:{active:"Active",archived:"Archived",archive:"Archive",restore:"Restore",delete:"Delete",menu:"Conversation menu",emptyActive:"No active conversations yet.",emptyArchived:"No archived conversations.",deleteTitle:"Delete conversation?",deleteDescription:"This removes the conversation and its messages from this device."},
 ar:{active:"النشطة",archived:"المؤرشفة",archive:"أرشفة",restore:"استعادة",delete:"حذف",menu:"قائمة المحادثة",emptyActive:"لا توجد محادثات نشطة بعد.",emptyArchived:"لا توجد محادثات مؤرشفة.",deleteTitle:"حذف المحادثة؟",deleteDescription:"سيؤدي ذلك إلى إزالة المحادثة ورسائلها من هذا الجهاز."},
 fr:{active:"Actives",archived:"Archivées",archive:"Archiver",restore:"Restaurer",delete:"Supprimer",menu:"Menu de la conversation",emptyActive:"Aucune conversation active.",emptyArchived:"Aucune conversation archivée.",deleteTitle:"Supprimer la conversation ?",deleteDescription:"La conversation et ses messages seront supprimés de cet appareil."},
 es:{active:"Activas",archived:"Archivadas",archive:"Archivar",restore:"Restaurar",delete:"Eliminar",menu:"Menú de conversación",emptyActive:"No hay conversaciones activas.",emptyArchived:"No hay conversaciones archivadas.",deleteTitle:"¿Eliminar conversación?",deleteDescription:"La conversación y sus mensajes se eliminarán de este dispositivo."},
 de:{active:"Aktiv",archived:"Archiviert",archive:"Archivieren",restore:"Wiederherstellen",delete:"Löschen",menu:"Unterhaltungsmenü",emptyActive:"Keine aktiven Unterhaltungen.",emptyArchived:"Keine archivierten Unterhaltungen.",deleteTitle:"Unterhaltung löschen?",deleteDescription:"Die Unterhaltung und ihre Nachrichten werden von diesem Gerät entfernt."}
};
function ClinicianAICompanion(){
 const {roles}=useAuth(),{lang,dir}=useI18n(),navigate=useNavigate(),c=clinicianCopy[lang],mc=clinicianManageCopy[lang],ac=ATTACH_COPY[lang];
 const [chats,setChats]=useState<ClinicianChat[]>(readClinicianChats),[activeId,setActiveId]=useState(""),[text,setText]=useState(""),[sending,setSending]=useState(false),[error,setError]=useState(""),[patients,setPatients]=useState<PatientProfile[]>([]),[menuOpen,setMenuOpen]=useState(false),[chatMenuId,setChatMenuId]=useState<string|null>(null),[historyView,setHistoryView]=useState<"active"|"archived">("active"),[draft,setDraft]=useState<ClinicianAttachment|null>(null),[recording,setRecording]=useState(false),[recordSeconds,setRecordSeconds]=useState(0),[historyOpen,setHistoryOpen]=useState(false);
 const endRef=useRef<HTMLDivElement>(null),historyRef=useRef<HTMLElement>(null),historyToggleRef=useRef<HTMLButtonElement>(null),photoRef=useRef<HTMLInputElement>(null),fileRef=useRef<HTMLInputElement>(null),recorderRef=useRef<MediaRecorder|null>(null),recordingStreamRef=useRef<MediaStream|null>(null),recordingTimerRef=useRef<number|null>(null),recordingChunksRef=useRef<Blob[]>([]),recordingSecondsRef=useRef(0),objectUrlsRef=useRef(new Set<string>()),isTherapist=roles.includes("therapist")&&!roles.includes("doctor");
 const active=chats.find(chat=>chat.id===activeId)||null;
 const visibleChats=chats.filter(chat=>Boolean(chat.archived)===(historyView==="archived"));
 const save=(next:ClinicianChat[])=>{setChats(next);try{localStorage.setItem(CLINICIAN_AI_KEY,JSON.stringify(next))}catch{/* storage is optional */}};
 const closeHistory=useCallback(()=>setHistoryOpen(false),[]);
 const newChat=()=>{const stamp=now(),chat:ClinicianChat={id:id(),title:c.new,messages:[],createdAt:stamp,updatedAt:stamp,defaultTitle:true,archived:false};save([chat,...chats]);setActiveId(chat.id);setHistoryView("active");closeHistory();setChatMenuId(null)};
 useEffect(() => {
  let cancelled = false;

  async function loadData() {
   try {
    const patientResult = await api<PatientListResponse>("/patients?limit=200");
    if (!cancelled) setPatients(patientResult.patients || []);
   } catch {
    if (!cancelled) setPatients([]);
   }

   if (chats.length) return;
   try {
    const historyResult = await getAIChatHistory();
    if (cancelled || !historyResult.messages.length) return;
    const messages = historyResult.messages.flatMap((item) => ([
     { id: `${item.id}-u`, role: "user" as const, text: item.message, createdAt: item.created_at },
     { id: `${item.id}-a`, role: "assistant" as const, text: item.assistant_response, createdAt: item.created_at },
    ]));
    const stamp = messages[messages.length - 1]?.createdAt || now();
    const chat: ClinicianChat = {
     id: id(),
     title: historyResult.messages[0].message.slice(0, 54),
     messages,
     createdAt: historyResult.messages[0].created_at,
     updatedAt: stamp,
    };
    if (cancelled) return;
    setChats([chat]);
    setActiveId(chat.id);
    try { localStorage.setItem(CLINICIAN_AI_KEY, JSON.stringify([chat])); } catch { /* storage is optional */ }
   } catch {
    /* Existing empty-state UI remains available when history cannot load. */
   }
  }

  void loadData();
  return () => { cancelled = true; };
 }, []);
 useEffect(() => {
  if (!activeId) setActiveId(chats.find((chat) => !chat.archived)?.id || "");
 }, [chats, activeId]);
 useEffect(() => {
  endRef.current?.scrollIntoView({ behavior: "smooth" });
 }, [active?.messages.length, sending]);
 useEffect(()=>{
  if(!historyOpen)return;
  historyRef.current?.focus();
  const closeOnEscape=(event:globalThis.KeyboardEvent)=>{if(event.key==="Escape"){closeHistory();historyToggleRef.current?.focus()}};
  const closeOnOutside=(event:PointerEvent)=>{const target=event.target as Node;if(!historyRef.current?.contains(target)&&!historyToggleRef.current?.contains(target))closeHistory()};
  document.addEventListener("keydown",closeOnEscape);
  document.addEventListener("pointerdown",closeOnOutside);
  return()=>{document.removeEventListener("keydown",closeOnEscape);document.removeEventListener("pointerdown",closeOnOutside)};
 },[historyOpen,closeHistory]);
 const addMessages=(items:ClinicianMessage[],title?:string)=>{const stamp=now();if(active){save(chats.map(chat=>chat.id===active.id?{...chat,title:chat.messages.length?chat.title:(title||c.new).slice(0,54),defaultTitle:false,messages:[...chat.messages,...items],updatedAt:stamp}:chat))}else{const chat={id:id(),title:(title||c.new).slice(0,54),defaultTitle:!title,messages:items,createdAt:stamp,updatedAt:stamp};save([chat,...chats]);setActiveId(chat.id)}};
 const localReply=(value:string,template:ClinicianTemplate,route?:string)=>{addMessages([{id:id(),role:"user",text:value,createdAt:now()},{id:id(),role:"assistant",template,route,createdAt:now()}],value)};
 const semantic=(template?:ClinicianTemplate)=>template?c[template]:"";
 const routeFor=(value:string)=>{const q=value.toLocaleLowerCase();if(/review queue|review|قائمة المراجعة|مراجعة|révision|revisión|prüfliste/.test(q))return"/review-queue";if(/appointment|موعد|مواعيد|rendez-vous|cita|termin/.test(q))return"/appointments";if(/patient|مريض|المرضى|patient|paciente/.test(q))return"/patients";return""};
 const submit=async(event:FormEvent)=>{event.preventDefault();const value=text.trim();if((!value&&!draft)||sending)return;setText("");setMenuOpen(false);if(draft){sendAttachment();return}const lower=value.toLocaleLowerCase();if(/diagnos|prescrib|dosage|medication change|change treatment|تشخيص|وصف دواء|جرعة|تغيير العلاج|diagnosti|recetar|prescrire/.test(lower)){localReply(value,"boundary");return}const route=routeFor(value);const exact=patients.filter(patient=>{const name=patient.user?.full_name?.trim().toLocaleLowerCase();return name&&lower.includes(name)});if(exact.length>1){localReply(value,"patientAmbiguous","/patients");return}if(/open|show|view|افتح|اعرض|ouvrir|abre|öffnen/.test(lower)&&exact.length===1){const patient=exact[0],patientRoute=/report|تقرير|rapport|informe|bericht/.test(lower)?`/reports/${patient.id}`:`/patients/${patient.id}`;localReply(value,"navigation",patientRoute);return}if(/patient|مريض|patient|paciente/.test(lower)&&/open|show|view|افتح|اعرض|ouvrir|abre|öffnen/.test(lower)&&!exact.length){localReply(value,"patientMissing","/patients");return}if(route){localReply(value,"navigation",route);return}setSending(true);setError("");try{const saved=await sendAIChatMessage(value);addMessages([{id:`${saved.id}-u`,role:"user",text:value,createdAt:saved.created_at},{id:`${saved.id}-a`,role:"assistant",text:saved.assistant_response,createdAt:saved.created_at}],value)}catch{setError(c.retry);addMessages([{id:id(),role:"user",text:value,createdAt:now()}],value)}finally{setSending(false)}};
 const createObjectUrl=(blob:Blob)=>{const url=URL.createObjectURL(blob);objectUrlsRef.current.add(url);return url};
 const clearDraft=()=>{setDraft(current=>{if(current?.url&&objectUrlsRef.current.delete(current.url))URL.revokeObjectURL(current.url);return null})};
 const choose=(kind:"image"|"file",file?:File)=>{if(!file)return;clearDraft();setError("");setDraft({name:file.name,kind,url:createObjectUrl(file),size:file.size});setMenuOpen(false)};
 const stopRecording=()=>{if(recordingTimerRef.current){window.clearInterval(recordingTimerRef.current);recordingTimerRef.current=null}if(recorderRef.current?.state==="recording")recorderRef.current.stop()};
 const startRecording=async()=>{setMenuOpen(false);setError("");clearDraft();try{if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==="undefined")throw new Error("unsupported");const stream=await navigator.mediaDevices.getUserMedia({audio:true});recordingStreamRef.current=stream;recordingChunksRef.current=[];const recorder=new MediaRecorder(stream);recorderRef.current=recorder;recorder.ondataavailable=event=>{if(event.data.size)recordingChunksRef.current.push(event.data)};recorder.onstop=()=>{const blob=new Blob(recordingChunksRef.current,{type:recorder.mimeType||"audio/webm"});stream.getTracks().forEach(track=>track.stop());recordingStreamRef.current=null;recorderRef.current=null;setDraft({kind:"voice",url:createObjectUrl(blob),name:"voice-message.webm",size:blob.size,duration:Math.max(1,recordingSecondsRef.current)});setRecording(false)};recordingSecondsRef.current=0;setRecordSeconds(0);setRecording(true);recorder.start();const started=Date.now();recordingTimerRef.current=window.setInterval(()=>{const seconds=Math.floor((Date.now()-started)/1000);recordingSecondsRef.current=seconds;setRecordSeconds(seconds)},1000)}catch{setRecording(false);setError(ac.permission)}};
 const sendAttachment=()=>{if(!draft||sending)return;const attachment=draft;setDraft(null);addMessages([{id:id(),role:"user",attachment,createdAt:now()},{id:id(),role:"assistant",template:"attachment",createdAt:now()}],attachment.name)};
 const archiveChat=(chat:ClinicianChat)=>{save(chats.map(item=>item.id===chat.id?{...item,archived:!item.archived}:item));setChatMenuId(null);if(activeId===chat.id)setActiveId("")};
 const deleteChat=(chat:ClinicianChat)=>{if(!window.confirm(`${mc.deleteTitle}\n\n${mc.deleteDescription}`))return;chat.messages.forEach(message=>{if(message.attachment?.url&&objectUrlsRef.current.delete(message.attachment.url))URL.revokeObjectURL(message.attachment.url)});save(chats.filter(item=>item.id!==chat.id));if(activeId===chat.id)setActiveId("");setChatMenuId(null)};
 useEffect(()=>()=>{if(recordingTimerRef.current)window.clearInterval(recordingTimerRef.current);const recorder=recorderRef.current;if(recorder?.state==="recording"){recorder.onstop=null;recorder.stop()}recordingStreamRef.current?.getTracks().forEach(track=>track.stop());objectUrlsRef.current.forEach(url=>URL.revokeObjectURL(url))},[]);
 useEffect(()=>()=>{if(recorderRef.current?.state==="recording"){recorderRef.current.onstop=null;recorderRef.current.stop();recordingStreamRef.current?.getTracks().forEach(track=>track.stop());recordingStreamRef.current=null;recorderRef.current=null;if(recordingTimerRef.current)window.clearInterval(recordingTimerRef.current);recordingTimerRef.current=null;setRecording(false)}},[activeId]);
 return <div className="clinician-ai-page page page--wide" dir={dir}><header className="page__head"><div><span className="eyebrow">{c.eyebrow}</span><h1>{c.title}</h1><p className="page__sub">{c.description}</p></div></header><section className={`clinician-ai-workspace ${historyOpen?"is-history-open":""}`}><aside ref={historyRef} id="clinician-ai-history" className="clinician-ai-history" tabIndex={-1} aria-hidden={!historyOpen}><header><strong>{c.history}</strong><button type="button" onClick={newChat}>＋ {c.new}</button></header><div className="clinician-ai-history__tabs"><button type="button" className={historyView==="active"?"is-active":""} onClick={()=>{setHistoryView("active");setChatMenuId(null)}}>{mc.active}</button><button type="button" className={historyView==="archived"?"is-active":""} onClick={()=>{setHistoryView("archived");setChatMenuId(null)}}>{mc.archived}</button></div><div className="clinician-ai-history__list">{visibleChats.map(chat=><div className={`clinician-ai-history__item ${chat.id===activeId?"is-active":""}`} key={chat.id}><button type="button" onClick={()=>{setActiveId(chat.id);closeHistory()}}><strong>{chat.defaultTitle||clinicianDefaultTitles.has(chat.title)?c.new:chat.title}</strong><time>{new Intl.DateTimeFormat(lang,{dateStyle:"medium"}).format(new Date(chat.updatedAt))}</time></button><button type="button" aria-label={mc.menu} aria-expanded={chatMenuId===chat.id} onClick={()=>setChatMenuId(chatMenuId===chat.id?null:chat.id)}>•••</button>{chatMenuId===chat.id&&<div className="clinician-ai-chat-menu"><button type="button" onClick={()=>archiveChat(chat)}>{chat.archived?mc.restore:mc.archive}</button><button type="button" className="is-danger" onClick={()=>deleteChat(chat)}>{mc.delete}</button></div>}</div>)}{!visibleChats.length&&<p>{historyView==="archived"?mc.emptyArchived:mc.emptyActive}</p>}</div></aside><main className="clinician-ai-chat"><header className="clinician-ai-chat__header"><button ref={historyToggleRef} className="clinician-ai-history-toggle" type="button" onClick={()=>setHistoryOpen(open=>!open)} aria-label={c.history} aria-expanded={historyOpen} aria-controls="clinician-ai-history">☰</button><img src={neurobridgeAiMascot} alt=""/><div><strong>NeuroBridge AI</strong><span>{isTherapist?c.therapist:c.doctor}</span></div><button type="button" onClick={newChat} aria-label={c.new}>＋</button></header><div className="clinician-ai-safety">{c.safety}</div><div className="clinician-ai-thread" aria-live="polite">{(!active||!active.messages.length)&&<section className="clinician-ai-welcome"><span><img src={neurobridgeAiMascot} alt=""/></span><h2>{c.welcome}</h2><p>{clinicianHelp[lang]}</p><small>{clinicianContextNote[lang]}</small><div className="clinician-ai-suggestions">{clinicianSuggestions.map(suggestion=><button type="button" key={suggestion.id} onClick={()=>{setText(suggestion.title[lang]);requestAnimationFrame(()=>document.querySelector<HTMLTextAreaElement>(".clinician-ai-composer textarea")?.focus())}}><span><strong>{suggestion.title[lang]}</strong><small>{suggestion.helper[lang]}</small></span></button>)}</div></section>}{active?.messages.map(message=><div className={`clinician-ai-message clinician-ai-message--${message.role}`} key={message.id}>{message.role==="assistant"&&<img src={neurobridgeAiMascot} alt=""/>}<article dir="auto">{message.attachment?<div className="clinician-ai-attachment-message">{message.attachment.kind==="voice"?<audio src={message.attachment.url} controls preload="metadata"/>:message.attachment.kind==="image"?<img src={message.attachment.url} alt={message.attachment.name}/>:<span aria-hidden="true">▤</span>}<strong>{message.attachment.name}</strong><small>{formatLocalSize(message.attachment.size)}</small></div>:<p>{message.template?semantic(message.template):message.text}</p>}{message.route&&<button type="button" onClick={()=>navigate(message.route!)}>{c.open}</button>}</article></div>)}{sending&&<div className="clinician-ai-message clinician-ai-message--assistant"><img src={neurobridgeAiMascot} alt=""/><div className="clinician-ai-thinking"><span>{c.thinking}</span><i/><i/><i/></div></div>}<div ref={endRef}/></div>{error&&<p className="clinician-ai-error">{error}</p>}{recording&&<div className="clinician-ai-recording"><span><i/>{ac.recording} <b>{Math.floor(recordSeconds/60)}:{String(recordSeconds%60).padStart(2,"0")}</b></span><button type="button" onClick={stopRecording}>{ac.stop}</button></div>}{draft&&<div className="clinician-ai-draft">{draft.kind==="voice"?<audio src={draft.url} controls preload="metadata"/>:draft.kind==="image"?<img src={draft.url} alt=""/>:<span aria-hidden="true">▤</span>}<strong>{draft.name}</strong><small>{formatLocalSize(draft.size)}</small><button type="button" onClick={clearDraft}>{ac.remove}</button><button type="button" className="is-send" onClick={sendAttachment}>{ac.send}</button></div>}<form className="clinician-ai-composer" onSubmit={submit}><div className="clinician-ai-attach"><button type="button" aria-label={c.add} onClick={()=>setMenuOpen(!menuOpen)}>＋</button>{menuOpen&&<div><button type="button" onClick={()=>photoRef.current?.click()}>{c.photo}</button><button type="button" onClick={()=>fileRef.current?.click()}>{c.file}</button><button type="button" onClick={()=>void startRecording()}>{ac.voice}</button><button type="button" onClick={()=>setMenuOpen(false)}>{c.close}</button></div>}<input ref={photoRef} type="file" accept="image/*" onChange={event=>{choose("image",event.target.files?.[0]);event.currentTarget.value=""}}/><input ref={fileRef} type="file" onChange={event=>{choose("file",event.target.files?.[0]);event.currentTarget.value=""}}/></div><textarea rows={1} maxLength={2000} value={text} onChange={event=>setText(event.target.value)} onKeyDown={(event:KeyboardEvent<HTMLTextAreaElement>)=>{if(event.key==="Enter"&&!event.shiftKey){event.preventDefault();event.currentTarget.form?.requestSubmit()}}} placeholder={clinicianPlaceholder[lang]}/><button type="submit" disabled={sending||(!text.trim()&&!draft)} aria-label={c.send}><span aria-hidden="true">↑</span></button></form></main></section></div>
}
